<script>
(()=>{const start=()=>{const $=id=>document.getElementById('aii-'+id);if(!$('root')||!window.Panel)return;const root=$('root'),AR=root.dataset.lang==='ar',L=(a,e)=>AR?a:e,rows=v=>Array.isArray(v)?v:[];let data=null,busy=false,active='sources';
const labels={openai:'ChatGPT',gemini:'Gemini',perplexity:'Perplexity',claude:'Claude'},cats={own:L('موقعك','Your site'),competitor:L('منافس','Competitor'),ota:L('منصات حجز','Booking platforms'),reviews:L('تقييمات','Reviews'),forums:L('منتديات','Forums'),social:L('سوشيال وفيديو','Social and video'),reference:L('مراجع','Reference'),media:L('إعلام سفر','Travel media'),maps:L('خرايط','Maps'),government:L('جهات رسمية','Official bodies'),other:L('مواقع تانية','Other sites')};
const advice={ota:L('اعرض رحلاتك أو خدماتك على المنصة دي وخلي بياناتك كاملة.','List your trips or services on this platform and keep your details complete.'),reviews:L('اطلب من عملائك تقييمات هنا وردّ عليها.','Ask your customers for reviews here and reply to them.'),forums:L('شارك بإجابات مفيدة باسم شركتك في النقاشات اللي بتتكلم عن وجهتك.','Add helpful answers under your company name in threads about your destination.'),social:L('انشر فيديوهات أو منشورات عن خدماتك على المنصة دي.','Post videos or posts about your services on this platform.'),reference:L('اتأكد إن المعلومات العامة عن وجهتك وشركتك صحيحة ومحدّثة.','Check that public information about your destination and company is correct and current.'),media:L('تواصل مع المحررين عشان تتذكر في المقالات الجاية.','Reach out to editors to be included in upcoming articles.'),maps:L('كمّل ملف Google Business واتأكد من بياناته.','Complete your Google Business profile and check its details.'),government:L('اتأكد إنك مسجّل في قوايم الجهات الرسمية لو متاح.','Make sure you are listed by official bodies where possible.'),other:L('شوف الصفحة واعرف إزاي تتذكر فيها.','Open the page and see how you could be included.')};
const sent={positive:[L('إيجابي','Positive'),'aii-pos'],neutral:[L('محايد','Neutral'),''],negative:[L('سلبي','Negative'),'aii-neg'],mixed:[L('مختلط','Mixed'),'aii-mix']},purposes={training:L('تدريب النماذج','Model training'),search:L('فهرسة للبحث','Search indexing'),user:L('زيارة بطلب مستخدم','Fetched for a user')};
const none=L('مفيش','none');
const node=(t,x,c)=>{const n=document.createElement(t);if(x!==undefined)n.textContent=x;if(c)n.className=c;return n;};
const msg=(t,e=false)=>{$('message').textContent=t;$('message').hidden=!t;$('message').dataset.error=String(e);};
const pct=v=>v==null||!Number.isFinite(Number(v))?'—':(Number(v)*100).toFixed(1)+'%';
const base=()=>({website_id:Number($('site').value),market_id:Number($('market').value||0),provider:$('provider').value});
function table(id,list,cols,emptyText){const d=$(id);if(!list.length){d.replaceChildren(node('p',emptyText,'aii-empty'));return;}const t=node('table',undefined,'p-table'),h=t.createTHead().insertRow();cols.forEach(c=>{const th=node('th',c[1]);th.scope='col';h.append(th);});const b=t.createTBody();list.forEach(r=>{const tr=b.insertRow();cols.forEach(c=>{const td=tr.insertCell(),v=typeof c[0]==='function'?c[0](r):r[c[0]];if(v instanceof Node)td.append(v);else td.textContent=String(v??'—');});});d.replaceChildren(t);}
function link(url,text){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw 0;const a=node('a',text||u.hostname);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch{return node('span',text||'');}}
function gate(){root.setAttribute('aria-busy',String(busy));root.querySelectorAll('button,select,input').forEach(c=>c.disabled=busy);$('reload').textContent=busy?L('جارٍ التحميل…','Loading…'):L('تحديث','Refresh');}
function tab(name){active=name;for(const k of ['sources','sentiment','crawlers','claude']){$('pane-'+k).hidden=k!==name;$('tab-'+k).setAttribute('aria-selected',String(k===name));$('tab-'+k).tabIndex=k===name?0:-1;}}
for(const k of ['sources','sentiment','crawlers','claude'])$('tab-'+k).onclick=()=>tab(k);
async function call(path,body){const csrf=root.dataset.csrf,isForm=body instanceof FormData;if(isForm)body.append('csrf_token',csrf);const r=await window.Panel.fetchJSON(path,body===undefined?undefined:{method:'POST',headers:Object.assign({'X-CSRF-Token':csrf},isForm?{}:{'Content-Type':'application/json'}),body:isForm?body:JSON.stringify({...base(),...body,csrf_token:csrf})});if(!r?.success)throw Error(r?.error||r?.message||L('تعذر إتمام الطلب. حاول تاني.','The request could not be completed. Try again.'));return r.data;}
async function work(fn,ok=''){if(busy)return;busy=true;msg('');gate();try{await fn();if(ok)msg(ok);}catch(e){msg(e.message||L('تعذر إتمام الطلب.','The request could not be completed.'),true);}finally{busy=false;gate();}}
function drawSources(s){$('sources-coverage').textContent=s.answers?L(s.answers_with_sources+' إجابة فيها مصادر من '+s.answers+' إجابة محفوظة خلال آخر 8 أسابيع. الموقع بيتحسب مرة واحدة في كل إجابة.',s.answers_with_sources+' of '+s.answers+' saved answers from the last 8 weeks cite sources. Each site counts once per answer.'):L('لسه مفيش إجابات محفوظة. فعّل قياس الظهور ووافق على الأسئلة، والنتائج هتظهر هنا بعد أول قياس أسبوعي.','No saved answers yet. Turn on visibility checks and approve your questions; results appear here after the first weekly check.');
const box=$('categories');box.replaceChildren();for(const [k,v] of Object.entries(s.categories||{}))box.append(node('span',(cats[k]||k)+': '+v,'aii-chip'));
table('gaps',rows(s.gaps),[[r=>link('https://'+r.host,r.host),L('الموقع','Site')],[r=>cats[r.category]||r.category,L('النوع','Type')],['competitor_only',L('إجابات فيها منافسين بدونك','Answers with competitors, not you')],[r=>advice[r.category]||advice.other,L('تعمل إيه','What to do')],[r=>link(r.example_url,L('مثال','Example')),L('صفحة مستشهد بيها','Cited page')]],L('مفيش فجوات واضحة في الإجابات المحفوظة.','No clear gaps in the saved answers.'));
table('sources',rows(s.sources),[[r=>link('https://'+r.host,r.host),L('الموقع','Site')],[r=>cats[r.category]||r.category,L('النوع','Type')],['answers',L('عدد الإجابات','Answers')],[r=>pct(r.share),L('من الإجابات اللي فيها مصادر','Of answers with sources')],['with_brand',L('مع ذكر شركتك','With your company')],[r=>rows(r.providers).map(p=>labels[p]||p).join(L('، ',', ')),L('المحركات','Engines')]],L('لسه مفيش مصادر.','No sources yet.'));}
function drawSentiment(s){const c=$('sent-cards');c.replaceChildren();for(const [k,[l,cls]] of Object.entries(sent)){const a=node('article',undefined,'aii-box');a.append(node('h3',l),node('div',String((s.totals||{})[k]||0),'aii-stat '+cls),node('p',L('إجابة','answers'),'aii-muted'));c.append(a);}
$('sent-pending').textContent=s.pending?L(s.pending+' إجابة ذكرت شركتك ولسه متحللتش.',s.pending+' answers mention your company and are not analyzed yet.'):L('كل الإجابات اللي ذكرت شركتك اتحللت.','Every answer that mentions your company has been analyzed.');$('sent-run').hidden=!s.pending;
table('sent-recent',rows(s.recent),[[r=>labels[r.provider]||r.provider,L('المحرك','Engine')],[r=>{const [l,cls]=sent[r.sentiment]||[r.sentiment,''];return node('span',l,cls);},L('الانطباع','Tone')],['excerpt',L('الجملة','Sentence')],['reason',L('السبب','Reason')],['question',L('السؤال','Question')],['checked_at',L('تاريخ القياس','Checked at')]],L('بعد التحليل، الجمل اللي بتوصف شركتك هتظهر هنا (السلبي الأول).','After analysis, sentences describing your company appear here, negative first.'));}
function drawCrawlers(s){const c=$('crawl-cards');c.replaceChildren();const total=rows(s.bots).reduce((n,b)=>n+b.hits,0);const card=(t,v,sub)=>{const a=node('article',undefined,'aii-box');a.append(node('h3',t),node('div',String(v),'aii-stat'),node('p',sub,'aii-muted'));c.append(a);};card(L('كل الزيارات','All visits'),total,L('آخر '+s.days+' يوم','Last '+s.days+' days'));for(const [k,l] of Object.entries(purposes))card(l,(s.purpose||{})[k]||0,L('زيارة','visits'));
const src=s.sources||{};$('crawl-basis').textContent=L('التعرّف على البوت من اسمه (User-Agent) بس، من غير التحقق من عنوان IP. آخر سجل مرفوع: ','Crawlers are identified by user-agent only, without IP verification. Last uploaded log: ')+(src.log||none)+L(' · آخر زيارة مباشرة: ',' · Last live visit: ')+(src.live||none);
table('crawl-bots',rows(s.bots),[['bot',L('البوت','Crawler')],['owner',L('الشركة','Company')],[r=>purposes[r.purpose]||r.purpose,L('الغرض','Purpose')],['hits',L('الزيارات','Visits')],['pages',L('صفحات مختلفة','Distinct pages')],['last_seen',L('آخر زيارة (UTC)','Last visit (UTC)')]],L('لسه مفيش زيارات مسجّلة. ارفع سجل الزيارات أو ركّب كود التتبع تحت.','No visits recorded yet. Upload an access log or install the tracking snippet below.'));
table('crawl-pages',rows(s.pages),[['path',L('الصفحة','Page')],['hits',L('الزيارات','Visits')],['bots',L('عدد البوتات','Crawlers')]],L('لسه مفيش صفحات.','No pages yet.'));$('token').textContent=s.token_set?L('إنشاء كود جديد (القديم هيبطل)','Create a new snippet (the old one stops working)'):L('إنشاء كود التتبع','Create tracking snippet');}
function drawClaude(c){$('tab-claude').hidden=!c;if(!c)return;$('claude-enabled').value=c.enabled?'1':'0';$('claude-model').replaceChildren(...rows(c.models).map(m=>new Option(m,m)));$('claude-model').value=c.model;
$('claude-status').textContent=c.registered===false?L('Claude مش متركّب على السيرفر ده. شغّل tools/install_ai_insights.php وشوف التقرير.','Claude is not installed on this server. Run tools/install_ai_insights.php and check its report.'):c.measuring?L('Claude بيتقاس دلوقتي مع باقي المحركات في القياس الأسبوعي.','Claude is measured with the other engines in the weekly check.'):!c.key_present?L('مفيش مفتاح Anthropic محفوظ. ضيفه من الإعدادات ← إعدادات الربط، وبعدين فعّل Claude هنا.','No Anthropic key is saved. Add it in Settings → Connection settings, then turn Claude on here.'):!c.geo_enabled?L('قياس ظهور AI كله متوقف من إعدادات النظام. شغّله الأول.','AI visibility checks are turned off in system settings. Turn them on first.'):L('Claude متوقف.','Claude is off.');}
async function load(){if(!$('site').dataset.ready){const r=await window.Panel.fetchJSON('/api/websites');if(!r?.success)throw Error(r?.error||L('تعذر تحميل المواقع.','Could not load your websites.'));const sites=rows(r.data?.websites||r.data?.items||r.data);const want=$('site').value||new URLSearchParams(location.search).get('website_id');$('site').replaceChildren(...sites.map(s=>new Option(s.name||s.domain||s.main_url||s.url||L('موقعي','My website'),s.id)));if(sites.some(s=>String(s.id)===want))$('site').value=want;$('site').dataset.ready='1';}
if(!base().website_id){msg(L('ضيف موقعك الأول من صفحة المواقع.','Add your website first from the Websites page.'),true);return;}const prev=$('market').value;data=await call('/api/ai-insights/data?'+new URLSearchParams(base()));
$('market').replaceChildren(new Option(L('كل الأسواق','All markets'),'0'),...rows(data.markets).map(m=>new Option(m.label,m.id)));if([...$('market').options].some(o=>o.value===prev))$('market').value=prev;
drawSources(data.sources||{});drawSentiment(data.sentiment||{});drawCrawlers(data.crawlers||{});drawClaude(data.claude);tab(active);}
$('reload').onclick=()=>work(load);$('site').onchange=()=>{$('market').value='0';$('snippet').hidden=true;work(load);};$('market').onchange=$('provider').onchange=()=>work(load);
$('sent-run').onclick=()=>work(async()=>{const r=await call('/api/ai-insights/sentiment',{});await load();msg(L('اتحلل '+r.classified+' إجابة'+(r.failed?'، و'+r.failed+' هتتحلل في محاولة تانية':'')+'.','Analyzed '+r.classified+' answers'+(r.failed?'; '+r.failed+' will be retried':'')+'.'));});
$('log-form').onsubmit=e=>{e.preventDefault();const f=new FormData();f.append('log',$('log').files[0]);f.append('website_id',String(base().website_id));work(async()=>{const r=await call('/api/ai-insights/crawler-log',f);await load();msg(L('اتقرا '+r.lines+' سطر، منهم '+r.ai_hits+' زيارة من بوتات AI على '+r.days+' يوم.','Read '+r.lines+' lines: '+r.ai_hits+' AI crawler visits across '+r.days+' days.'));});};
$('token').onclick=()=>{if(!confirm(L('الكود الجديد هيلغي أي كود قديم متركّب على موقعك. تكمل؟','A new snippet disables any old snippet installed on your site. Continue?')))return;work(async()=>{const r=await call('/api/ai-insights/crawler-token',{});$('snippet').textContent=r.snippet;$('snippet').hidden=false;await load();msg(r.note);});};
$('claude-form').onsubmit=e=>{e.preventDefault();work(async()=>{const r=await call('/api/admin/ai-insights/claude',{enabled:$('claude-enabled').value,model:$('claude-model').value});drawClaude({...data.claude,...r});},L('اتحفظت إعدادات Claude.','Claude settings saved.'));};
work(load);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
</script>
